import { createSlice } from '@reduxjs/toolkit';

// Define the initial state for the analytics slice
const initialState = {
  pageViews: 0,
  events: [],
  // Add other properties as needed
};

// Create the analytics slice
const analyticsSlice = createSlice({
  name: 'analytics',
  initialState,
  reducers: {
    incrementPageViews: (state) => {
      state.pageViews += 1;
    },
    addEvent: (state, action) => {
      state.events.push(action.payload);
    },
    // Add other reducer actions as needed
  },
});

// Export the action creators generated by createSlice
export const { incrementPageViews, addEvent } = analyticsSlice.actions;

// Export the analytics reducer
export default analyticsSlice.reducer;
